function DeliveryRuleManager({rules,onSave,busy}:{rules:DeliveryRule[];onSave:(next:DeliveryRule[])=>Promise<boolean>;busy:boolean}){
 const [draft,setDraft]=useState<DeliveryRule[]>(rules||[]),[editingId,setEditingId]=useState<string|null>(null),[saving,setSaving]=useState(false),[error,setError]=useState('');
 useEffect(()=>{setDraft(rules||[])},[rules]);
 const add=()=>{const id=`delivery-${crypto.randomUUID()}`;setDraft(current=>[...current,{id,area:'',prefix:'',fee:0,enabled:false}]);setEditingId(id);setError('')};
 const patch=(id:string,value:Partial<DeliveryRule>)=>setDraft(current=>current.map(rule=>rule.id===id?{...rule,...value}:rule));
 const remove=(id:string)=>{if(!window.confirm('Delete this delivery rule? Customers in this PIN range will become unavailable unless another enabled rule matches.'))return;setDraft(current=>current.filter(rule=>rule.id!==id));if(editingId===id)setEditingId(null)};
 const save=async()=>{if(draft.some(rule=>!/^\d{3,6}$/.test(rule.prefix)||!Number.isFinite(rule.fee)||rule.fee<0||rule.fee>1_000_000||(rule.area||'').trim().length>120||(rule.enabled&&!rule.area?.trim()))){setError('Enter a 3–6 digit PIN prefix, a fee from ₹0 to ₹10,00,000, and an area name before enabling a rule. Use ₹0 for free delivery.');return}if(new Set(draft.map(rule=>rule.prefix)).size!==draft.length){setError('Each PIN prefix must be unique.');return}setSaving(true);setError('');try{if(await onSave(draft))setEditingId(null)}finally{setSaving(false)}};
 return <section className="delivery-rule-manager"><div className="delivery-rule-heading"><div><span className="panel-overline">CHECKOUT DELIVERY · ABAYA &amp; KANDURA</span><h3>PIN-code delivery fees</h3><p>Set only owner-approved service areas and fees. Rules match the PIN prefix; the most specific enabled match wins. Unmatched PINs remain unavailable. No fallback fee is active. Add the area name for your reference, a 3–6 digit PIN prefix and the approved fee. ₹0 means free delivery.</p></div><button type="button" className="admin-btn secondary" onClick={add} disabled={busy||saving}><Plus size={14}/> Add Rule</button></div>
 {(draft||[]).map((rule,index)=><article className="delivery-rule-card" key={rule.id}><div className="delivery-rule-summary"><div><b>{rule.area?.trim()||'Area name not set'}</b><small>PIN prefix {rule.prefix||'not set'} · {rule.fee===0?'FREE':money(rule.fee)} · {rule.enabled?'Enabled':'Disabled'}</small></div><div className="row-actions"><button type="button" className="admin-btn secondary" onClick={()=>setEditingId(editingId===rule.id?null:rule.id)} disabled={busy||saving}>{editingId===rule.id?'Close':'Edit'}</button><button type="button" className="icon-danger" onClick={()=>remove(rule.id)} disabled={busy||saving} aria-label={`Delete delivery rule ${index+1}`}><Trash2 size={13}/></button></div></div>{editingId===rule.id&&<div className="delivery-rule-row"><label>Area name<input value={rule.area||''} maxLength={120} onChange={event=>patch(rule.id,{area:event.target.value})} placeholder="Owner-approved delivery area"/></label><label>PIN prefix<input inputMode="numeric" maxLength={6} value={rule.prefix} onChange={event=>patch(rule.id,{prefix:event.target.value.replace(/\D/g,'').slice(0,6)})} placeholder="3–6 digits"/></label><label>Delivery fee (₹)<input type="number" min="0" max="1000000" step="1" value={rule.fee} onChange={event=>patch(rule.id,{fee:event.target.value===''?0:Number(event.target.value)})}/></label><label className="delivery-rule-enabled"><input type="checkbox" checked={rule.enabled} onChange={event=>patch(rule.id,{enabled:event.target.checked})}/> Enabled for customers</label></div>}</article>)}
 {!(draft||[]).length&&<p className="empty-state">No delivery rules are configured. Customers will see “Delivery unavailable for this PIN code” until the shop adds and enables a rule using verified service-area and fee information.</p>}
 <div className="delivery-rule-footer"><small>New rules start disabled. Enter the shop’s confirmed area, PIN prefix and fee, enable only after verification, then save. There is no default-fee fallback.</small><button type="button" className="admin-btn primary" onClick={()=>void save()} disabled={busy||saving||!draft.length}><Check size={14}/>{saving?'Saving delivery rules…':'Save delivery rules'}</button></div>{error&&<p role="alert" className="checkout-delivery-error">{error}</p>}</section>
}

